"""Temporary selected tridiagonal GPU experiment; not a production backend."""
import json,time,hashlib
from pathlib import Path
import numpy as np,torch,warp as wp
from physics_engine.quantum import schrodinger_1d as cpu
import ctypes,subprocess
CUDA_SOURCE='\n#include <cuda_runtime.h>\n#include <math.h>\n__global__ void inverse(const double *d,double off,const double *ev,double *v,int n) {\n extern __shared__ double work[];\n double *p=work,*x=work+n;\n int j=blockIdx.x;\n if(threadIdx.x==0) {\n  double shift=ev[j]+1.e-7*fmax(1.,fabs(ev[j]));\n  p[0]=d[0]-shift;x[0]=1.;\n  for(int i=1;i<n;++i) {double q=d[i]-shift-off*off/p[i-1];if(fabs(q)<1.e-100)q=1.e-100;p[i]=q;x[i]=sin(double(i+1)*1.23456789);}\n  for(int it=0;it<4;++it) {\n   for(int i=1;i<n;++i)x[i]=x[i]-off*x[i-1]/p[i-1];\n   x[n-1]=x[n-1]/p[n-1];\n   for(int i=n-2;i>=0;--i)x[i]=(x[i]-off*x[i+1])/p[i];\n   double norm=0.;for(int i=0;i<n;++i)norm+=x[i]*x[i];norm=sqrt(norm);\n   for(int i=0;i<n;++i)x[i]=x[i]/norm;\n  }\n }\n __syncthreads();\n for(int i=threadIdx.x;i<n;i+=blockDim.x)v[j*n+i]=x[i];\n}\nextern "C" int run_inverse(const double *d,double off,const double *ev,double *v,int n,int k,void *stream) {\n inverse<<<k,128,2*n*sizeof(double),(cudaStream_t)stream>>>(d,off,ev,v,n);\n return (int)cudaGetLastError();\n}\n'
Path('/tmp/e_inverse.cu').write_text(CUDA_SOURCE)
subprocess.run(['nvcc','-O3','--fmad=false','-shared','-Xcompiler','-fPIC','/tmp/e_inverse.cu','-o','/tmp/e_inverse.so'],check=True)
lib=ctypes.CDLL('/tmp/e_inverse.so');lib.run_inverse.argtypes=[ctypes.c_void_p,ctypes.c_double,ctypes.c_void_p,ctypes.c_void_p,ctypes.c_int,ctypes.c_int,ctypes.c_void_p];lib.run_inverse.restype=ctypes.c_int

wp.set_module_options({'enable_backward':False,'fast_math':False,'fuse_fp':False})
@wp.kernel
def selected(d:wp.array(dtype=wp.float64),off:wp.float64,lo:wp.float64,hi:wp.float64,ev:wp.array(dtype=wp.float64)):
    j=wp.tid();n=d.shape[0];a=lo;b=hi
    for it in range(64):
        x=(a+b)*wp.float64(.5);q=d[0]-x;count=int(0)
        if wp.abs(q)<wp.float64(1.e-100):q=wp.float64(-1.e-100)
        if q<wp.float64(0.):count+=1
        for i in range(1,n):
            q=d[i]-x-off*off/q
            if wp.abs(q)<wp.float64(1.e-100):q=wp.float64(-1.e-100)
            if q<wp.float64(0.):count+=1
        if count<=j:a=x
        else:b=x
    ev[j]=(a+b)*wp.float64(.5)
@wp.kernel
def bracket_counts(d:wp.array(dtype=wp.float64),off:wp.float64,bounds:wp.array2d(dtype=wp.float64),counts:wp.array2d(dtype=wp.int32)):
    j,lane=wp.tid();n=d.shape[0];a=bounds[j,0];b=bounds[j,1]
    x=a+(b-a)*wp.float64(lane+1)/wp.float64(32.);q=d[0]-x;count=int(0)
    if wp.abs(q)<wp.float64(1.e-100):q=wp.float64(-1.e-100)
    if q<wp.float64(0.):count+=1
    for i in range(1,n):
        q=d[i]-x-off*off/q
        if wp.abs(q)<wp.float64(1.e-100):q=wp.float64(-1.e-100)
        if q<wp.float64(0.):count+=1
    counts[j,lane]=count
@wp.kernel
def bracket_update(bounds:wp.array2d(dtype=wp.float64),counts:wp.array2d(dtype=wp.int32),ev:wp.array(dtype=wp.float64)):
    j=wp.tid();a=bounds[j,0];b=bounds[j,1];left=a;right=b
    for lane in range(31):
        x=a+(b-a)*wp.float64(lane+1)/wp.float64(32.)
        if counts[j,lane]<=j:left=wp.max(left,x)
        else:right=wp.min(right,x)
    bounds[j,0]=left;bounds[j,1]=right;ev[j]=(left+right)*wp.float64(.5)
@wp.kernel
def vectors(d:wp.array(dtype=wp.float64),off:wp.float64,ev:wp.array(dtype=wp.float64),p:wp.array2d(dtype=wp.float64),v:wp.array2d(dtype=wp.float64)):
    j=wp.tid();n=d.shape[0];shift=ev[j]+wp.float64(1.e-7)*wp.max(wp.float64(1.),wp.abs(ev[j]))
    p[j,0]=d[0]-shift
    v[j,0]=wp.float64(1.)
    for i in range(1,n):
        q=d[i]-shift-off*off/p[j,i-1]
        if wp.abs(q)<wp.float64(1.e-100):q=wp.float64(1.e-100)
        p[j,i]=q;v[j,i]=wp.sin(wp.float64(i+1)*wp.float64(1.23456789))
    for it in range(4):
        for i in range(1,n):v[j,i]=v[j,i]-off*v[j,i-1]/p[j,i-1]
        v[j,n-1]=v[j,n-1]/p[j,n-1]
        for back in range(n-1):
            i=n-2-back;v[j,i]=(v[j,i]-off*v[j,i+1])/p[j,i]
        norm=wp.float64(0.)
        for i in range(n):norm+=v[j,i]*v[j,i]
        norm=wp.sqrt(norm)
        for i in range(n):v[j,i]=v[j,i]/norm

def solve(V,dx,k):
    diagonal=1./dx**2+V;off=-.5/dx**2;n=len(V)
    d=wp.array(diagonal,dtype=wp.float64,device='cuda');e=wp.empty(k,dtype=wp.float64,device='cuda');p=wp.empty((k,n),dtype=wp.float64,device='cuda');v=wp.empty_like(p)
    bounds=wp.array(np.tile([float(diagonal.min()-2*abs(off)),float(diagonal.max()+2*abs(off))],(k,1)),dtype=wp.float64,device='cuda')
    counts=wp.empty((k,31),dtype=wp.int32,device='cuda')
    for _ in range(13):
        wp.launch(bracket_counts,(k,31),inputs=[d,off,bounds,counts],device='cuda')
        wp.launch(bracket_update,k,inputs=[bounds,counts,e],device='cuda')
    rc=lib.run_inverse(d.ptr,off,e.ptr,v.ptr,n,k,wp.get_stream('cuda').cuda_stream)
    if rc:raise RuntimeError(f'CUDA inverse launch error {rc}')
    return e.numpy(),v.numpy().T/np.sqrt(dx)
wp.init();torch.set_num_threads(1);solve(np.zeros(16),.1,3)
rows=[]
for case in ('oscillator','well','asymmetric'):
 n=2000;x=np.linspace(-6,6,n);dx=x[1]-x[0];V=.5*x*x;k=6
 if case=='well':V=np.zeros(n);dx=1./(n-1);k=5
 if case=='asymmetric':V+=.12*np.sin(1.7*x)
 E,P=cpu.solve(V,dx,k)
 for repeat in range(2):
  t=time.perf_counter();G,Q=solve(V,dx,k);elapsed=time.perf_counter()-t
  Q*=np.where(np.sum(P*Q,axis=0)<0,-1.,1.)
  residual=(1/dx**2+V)[:,None]*Q-G*Q;residual[1:]+=-.5/dx**2*Q[:-1];residual[:-1]+=-.5/dx**2*Q[1:]
  rows.append(dict(case=case,repeat=repeat,seconds=elapsed,energy_error=float(np.max(np.abs(G-E))),vector_error=float(np.max(np.abs(Q-P))),vector_normalized=float(np.max(np.abs(Q-P)/(1.e-8+1.e-6*np.abs(P)))),residual=float(np.max(np.abs(residual))),orthogonality=float(np.max(np.abs(Q.T@Q*dx-np.eye(k)))),energies=G.tolist()))
out=Path('reports/schrodinger_shared_experiment_v1');out.mkdir(parents=True,exist_ok=True);(out/'report.json').write_text(json.dumps(dict(device=torch.cuda.get_device_name(),rows=rows,source=Path(__file__).read_text()),indent=2)+'\n');print(rows)
